use xiom.io;

use xiom.string;
module data {
  pub type Item = {
    name: Str;
    price: Int;
  }

  pub fn new_item(name: Str, price: Int) -> Item {
    return Item{ name: name, price: price };
  }
}

module pricing {
  pub fn apply_discount(price: Int, percent: Int) -> Int {
    return price - (price * percent / 100);
  }
}

module store {
  pub fn sell_item(name: Str, price: Int) -> Int {
    let item = data.new_item(name, price);
    return pricing.apply_discount(item.price, 20);
  }
}

fn main() -> Int {
  let final_price = store.sell_item("Widget", 100);
  io.println(string.int_to_str(final_price));
  return 0;
}
